type SetUserActiveParams struct {
	IsActive bool        `json:"is_active"`
	ActorID  pgtype.UUID `json:"actor_id"`
	ID       pgtype.UUID `json:"id"`
}

type SetUserActiveRow struct {
	ID                pgtype.UUID        `json:"id"`
	Email             string             `json:"email"`
	Name              string             `json:"name"`
	IsActive          bool               `json:"is_active"`
	CreatedAt         pgtype.Timestamptz `json:"created_at"`
	DeactivatedAt     pgtype.Timestamptz `json:"deactivated_at"`
	LastLoginAt       pgtype.Timestamptz `json:"last_login_at"`
	DeactivatedByName string             `json:"deactivated_by_name"`
	Workspaces        []string           `json:"workspaces"`
	ResetExpiresAt    pgtype.Timestamptz `json:"reset_expires_at"`
}

// A deactivation records who made it and when, unless the account was
// already inactive; a reactivation clears both. A deactivation also ends
// every session, so reactivating the account revives none of them.
func (q *Queries) SetUserActive(ctx context.Context, arg SetUserActiveParams) (SetUserActiveRow, error) {
	row := q.db.QueryRow(ctx, setUserActive, arg.IsActive, arg.ActorID, arg.ID)
	var i SetUserActiveRow
	err := row.Scan(
		&i.ID,
		&i.Email,
		&i.Name,
		&i.IsActive,
		&i.CreatedAt,
		&i.DeactivatedAt,
		&i.LastLoginAt,
		&i.DeactivatedByName,
		&i.Workspaces,
		&i.ResetExpiresAt,
	)
	return i, err
}

const tombstoneUser = `-- name: TombstoneUser :exec
UPDATE users SET email = 'deleted-' || id::text || '@deleted.invalid', name = 'Deleted account',
       password_hash = $1, theme = NULL, tokens_valid_from = NOW(),
       deleted_at = NOW(), deleted_by = $2::uuid, updated_at = NOW()
WHERE id = $3
`

type TombstoneUserParams struct {
	PasswordHash string      `json:"password_hash"`
	ActorID      pgtype.UUID `json:"actor_id"`
	ID           pgtype.UUID `json:"id"`
}

// The account's row stays (D-57); what identified the person goes.
func (q *Queries) TombstoneUser(ctx context.Context, arg TombstoneUserParams) error {
	_, err := q.db.Exec(ctx, tombstoneUser, arg.PasswordHash, arg.ActorID, arg.ID)
	return err
}

const userIDExists = `-- name: UserIDExists :one
SELECT EXISTS(SELECT 1 FROM users WHERE id = $1) AS user_exists
`

func (q *Queries) UserIDExists(ctx context.Context, id pgtype.UUID) (bool, error) {
	row := q.db.QueryRow(ctx, userIDExists, id)
	var user_exists bool
	err := row.Scan(&user_exists)
	return user_exists, err
}

const usersExist = `-- name: UsersExist :one
SELECT EXISTS(SELECT 1 FROM users) AS users_exist
`

func (q *Queries) UsersExist(ctx context.Context) (bool, error) {
	row := q.db.QueryRow(ctx, usersExist)
	var users_exist bool
	err := row.Scan(&users_exist)
	return users_exist, err
}

const writeInstanceAudit = `-- name: WriteInstanceAudit :exec
INSERT INTO instance_audit_log (actor_id, action, target_user_id, detail)
VALUES ($1::uuid, $2, $3::uuid, $4::jsonb)
`

type WriteInstanceAuditParams struct {
	ActorID      pgtype.UUID `json:"actor_id"`
	Action       string      `json:"action"`
	TargetUserID pgtype.UUID `json:"target_user_id"`
	Detail       []byte      `json:"detail"`
}

func (q *Queries) WriteInstanceAudit(ctx context.Context, arg WriteInstanceAuditParams) error {
	_, err := q.db.Exec(ctx, writeInstanceAudit,
		arg.ActorID,
		arg.Action,
		arg.TargetUserID,
		arg.Detail,
	)
	return err
}
